function findMaxConsecutiveOnes(nums) {
  let best = 0;
  let current = 0;
  for (const num of nums) {
    if (num === 1) {
      current++;
      best = Math.max(best, current);
    } else {
      current = 0;
    }
  }
  return best;
}

