function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 12);
  const density = [0, 0.3, 0.5, 0.8, 0.95, 1][Math.floor(rand() * 6)];
  return [Array.from({ length: n }, () => (rand() < density ? 1 : 0))];
}
